{
  "findings": [
    {
      "check_id": "CKV_AWS_277",
      "title": "Security group permits unrestricted public ingress",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "Every TCP port supplied through var.ingress_ports is exposed to all IPv4 addresses. This makes the Vault service reachable from untrusted internet sources on each configured port."
    }
  ],
  "patched_code": "resource "aws_security_group" "vault" {
  name        = "vault"
  description = "Ingress for Vault"
  vpc_id      = aws_vpc.my_vpc.id
  dynamic "ingress" {
    iterator = port
    for_each = var.ingress_ports
    content {
      from_port   = port.value
      to_port     = port.value
      protocol    = "tcp"
      cidr_blocks = [aws_vpc.my_vpc.cidr_block]
    }
  }
}
",
  "fix_summary": "Restricted Vault ingress to the VPC CIDR instead of allowing connections from the entire internet."
}
